import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { quests } from "../apps/api/src/quests.js";

const projectRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const outputPath = path.join(projectRoot, "apps/web/quest-catalog.generated.js");
const publicQuests = quests.map((quest) => ({
  ...quest,
  questions: quest.questions.map(({ answerIndex, explanation, ...question }) => question)
}));
const source = [
  "// Generated by scripts/generate-web-catalog.mjs. Do not edit by hand.",
  `export const catalogQuests = ${JSON.stringify(publicQuests, null, 2)};`,
  ""
].join("\n");

fs.writeFileSync(outputPath, source);
